function signalBurst({ readings, width, threshold }) {
    let best = 0;
    for (let start = 0; start + width <= readings.length; start++) {
        let count = 0;
        for (let j = start; j < start + width; j++)
            if (readings[j] >= threshold)
                count++;
        best = Math.max(best, count);
    }
    return best;
}

function signalBurst({ readings, width, threshold }) {
    let count = 0;
    for (let j = 0; j < width; j++)
        if (readings[j] >= threshold)
            count++;
    let best = count;
    for (let j = width; j < readings.length; j++) {
        if (readings[j - width] >= threshold)
            count--;
        if (readings[j] >= threshold)
            count++;
        best = Math.max(best, count);
    }
    return best;
}
